// Check if lead already has validated email - skip if so
const lead = $input.first().json.record || $input.first().json;

if (lead.email_validated) {
  return []; // Skip - already enriched
}

return [{ json: lead }];

// Extract domain from company website for email pattern generation
const lead = $input.first().json;
let domain = null;

if (lead.company_website) {
  try {
    const url = lead.company_website.startsWith('http') 
      ? lead.company_website 
      : `https://${lead.company_website}`;
    domain = new URL(url).hostname.replace('www.', '');
  } catch (e) {
    domain = lead.company_website.replace(/^(https?:\/\/)?(www\.)?/, '').split('/')[0];
  }
}

// Generate email patterns for Brazilian law firms
const patterns = [];
const firstName = (lead.first_name || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const lastName = (lead.last_name || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

if (domain && firstName) {
  // Common patterns for Brazilian law firms
  patterns.push(`${firstName}@${domain}`);
  if (lastName) {
    patterns.push(`${firstName}.${lastName}@${domain}`);
    patterns.push(`${firstName}${lastName.charAt(0)}@${domain}`);
    patterns.push(`${firstName.charAt(0)}${lastName}@${domain}`);
  }
  // Generic patterns
  patterns.push(`contato@${domain}`);
  patterns.push(`juridico@${domain}`);
  patterns.push(`escritorio@${domain}`);
}

return [{
  json: {
    ...lead,
    _domain: domain,
    _email_patterns: patterns,
    _enrichment_started: new Date().toISOString()
  }
}];

// Process Hunter.io results and determine best email
const lead = $('Extract Domain & Generate Patterns').first().json;
const hunterResult = $input.first().json;

let foundEmail = null;
let emailSource = null;

// Check Hunter.io results
if (hunterResult.data && hunterResult.data.emails && hunterResult.data.emails.length > 0) {
  // Try to find personal email matching the lead's name
  const firstName = (lead.first_name || '').toLowerCase();
  const personalEmail = hunterResult.data.emails.find(e => 
    e.first_name && e.first_name.toLowerCase() === firstName
  );

  if (personalEmail) {
    foundEmail = personalEmail.value;
    emailSource = 'hunter_api_personal';
  } else {
    // Use first generic email
    foundEmail = hunterResult.data.emails[0].value;
    emailSource = 'hunter_api_generic';
  }
} else if (lead._email_patterns && lead._email_patterns.length > 0) {
  // Fallback to pattern-generated email (first personal pattern)
  foundEmail = lead._email_patterns[0];
  emailSource = 'pattern_generated';
}

return [{
  json: {
    ...lead,
    _found_email: foundEmail,
    _email_source: emailSource
  }
}];

// Process validation result and determine if email is usable
const lead = $('Process Email Results').first().json;
const validation = $input.first().json;

let emailValidated = false;
let validationStatus = 'unknown';

// Parse validation result (adapt based on chosen API)
if (validation) {
  // AbstractAPI format
  if (validation.deliverability === 'DELIVERABLE') {
    emailValidated = true;
    validationStatus = 'valid';
  } else if (validation.is_catchall_email) {
    emailValidated = true; // Accept catch-all with flag
    validationStatus = 'catch_all';
  } else if (validation.deliverability === 'UNDELIVERABLE') {
    emailValidated = false;
    validationStatus = 'invalid';
  }
  // NeverBounce format
  else if (validation.result === 'valid') {
    emailValidated = true;
    validationStatus = 'valid';
  } else if (validation.result === 'catchall') {
    emailValidated = true;
    validationStatus = 'catch_all';
  } else if (validation.result === 'invalid' || validation.result === 'disposable') {
    emailValidated = false;
    validationStatus = validation.result;
  }
}

// Determine final status
const newStatus = emailValidated ? 'enriched' : 
  (lead._found_email ? 'unqualified' : 'unqualified');

return [{
  json: {
    lead_id: lead.id,
    email: emailValidated ? lead._found_email : lead.email,
    email_validated: emailValidated,
    status: newStatus,
    custom_fields: {
      ...(lead.custom_fields || {}),
      email_source: lead._email_source,
      email_validation_status: validationStatus,
      enriched_at: new Date().toISOString(),
      domain: lead._domain
    }
  }
}];

// Log enrichment summary
const items = $input.all();
const summary = {
  total_processed: items.length,
  emails_found: items.filter(i => i.json.email).length,
  emails_validated: items.filter(i => i.json.email_validated).length,
  enriched: items.filter(i => i.json.status === 'enriched').length,
  unqualified: items.filter(i => i.json.status === 'unqualified').length,
  completed_at: new Date().toISOString()
};

return [{ json: summary }];
